import { createHash } from "crypto";
import { OrderEventKind } from "../domain/order";

const KIND_CODE: Record<OrderEventKind, string> = {
  PAID: "paid",
  SHIPPED: "ship",
  DELIVERED: "dlvd",
};

/**
 * 논리 키 — 사내 키 규약 `<네임스페이스>.<이벤트>.<업무 식별자>`.
 * 같은 알림이면 항상 같은 값이다.
 */
export function logicalKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
  return `${namespace}.${KIND_CODE[kind]}.${orderNo}`;
}

/**
 * 와이어 키 — 논리 키 앞에 그 해시 16자를 둔다.
 * mqpub 은 한 배치 안에서 키 앞 16바이트가 같은 메시지를 중복으로 보고 첫 것만 저장하므로,
 * 공통 접두(네임스페이스·이벤트명)로 시작하는 논리 키는 앞부분이 서로 같아져 덮인다.
 * 해시를 맨 앞에 두면 메시지마다 앞 16바이트가 달라지고, 같은 알림은 늘 같은 키라 소비 측 중복 제거도 유지된다.
 */
export function messageKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
  const logical = logicalKey(namespace, kind, orderNo);
  const digest = createHash("sha1").update(logical).digest("hex").slice(0, 16);
  return `${digest}:${logical}`;
}

